from typing import List

def rolling_max(numbers: List[int]) -> List[int]:
    max_val = numbers[0]
    result = [0] * len(numbers)

    for i in range(len(numbers)):
        if numbers[i] > max_val:
            max_val = numbers[i]
        result[i] = max_val

    return result

