{
    var maxVal := numbers[0];
    var n := |numbers|;

    result := new int[n];

    // Populate the result with the rolling maximum
    for i := 0 to n - 1 {
        if numbers[i] > maxVal {
            maxVal := numbers[i];
        }
        result[i] := maxVal;
    }
